        boolean shouldSlowDown;
        PlayerPatch playerPatch;
        SkillContainer skill;
        if (self.isLinkAnimation()) {
            return 1.0f;
        }
        boolean shouldRelease = false;
        boolean isZansetsuActive = false;
        if (entitypatch instanceof PlayerPatch && (skill = (playerPatch = (PlayerPatch)entitypatch).getSkill((SkillSlot)SkillSlots.WEAPON_INNATE)) != null) {
            SkillDataManager dataManager = skill.getDataManager();
