                shouldRelease = (Boolean)dataManager.getDataValue((SkillDataKey)EFNSKillDataKeys.MURASAMA_ZANSETSU_SLASH_RELEASED.get());
            }
        }
        float currentFrame = elapsedTime * 60.0f;
        boolean bl = shouldSlowDown = isZansetsuActive && !shouldRelease && currentFrame <= 6.0f;
        if (!shouldSlowDown) {
            return 1.1f;
        }
